        if (!r || r.state !== st) probs.push(id + ' state ' + (r && r.state) + ' (expected ' + st + ')')
        if (g && !new RegExp('"rung": "' + id + '"[^}]*"state": "' + st + '"').test(g.prompt)) probs.push('gather prompt does not list ' + id + ' as ' + st)
      }
    }
    if (sc.gateJudgeTier) {
      const j = calls.find(c => c.label === 'judge:gate')
