function bounds(text) {
  const lines = text.split('\n')
  const start = lines.findIndex(l => l.startsWith('// MANIFEST - the coordinator replaces')) - 1
  const end = lines.findIndex(l => l.startsWith('// =========================== END MANIFEST'))
